## Code Example

```javascript
interface Limiter {
  tryAcquire(key: string, tokens: number): boolean;
}
class TokenBucketLimiter implements Limiter { /* ... */ }
class LeakyBucketLimiter implements Limiter { /* ... */ }
class FixedWindowLimiter implements Limiter { /* ... */ }
class Registry {
  private factories = new Map<string, () => Limiter>();
  register(name: string, factory: () => Limiter) { this.factories.set(name, factory); }
  create(name: string): Limiter | null { const f = this.factories.get(name); return f ? f() : null; }
}
class RateLimiterEngine {
  constructor(private registry: Registry, private defaultName: string = 'token') {}
  canAccess(key: string, tokens = 1): boolean {
    const limiter = this.registry.create(this.defaultName);
    return limiter ? limiter.tryAcquire(key, tokens) : false;
  }
}
